mapper.update:
UPDATE sys_article_collect
SET operation_count = operation_count + 1,
    last_collect_time = NOW()
WHERE user_id = #{userId}
  AND article_id = #{articleId}

UPDATE sys_article SET quantity = CASE
WHEN id = #{article.id} THEN #{article.quantity}
END WHERE id IN
#{article.id}

UPDATE sys_article_collect
SET operation_count = operation_count + 1,
    last_uncollect_time = NOW()
WHERE user_id = #{userId}
  AND article_id = #{articleId}

mapper.select:
SELECT a.id, a.title, a.summary, a.cover, a.is_recommend, a.quantity, a.status, a.is_archive, a.create_time, a.update_time, a.first_accessed_time, a.last_accessed_time, c.name AS categoryName, u.nickname, u.avatar FROM sys_article a LEFT JOIN sys_category c ON a.category_id = c.id left join sys_user u on a.user_id = u.id
a.status = #{query.status}
and a.title like concat('%',#{query.title},'%')
and a.category_id = #{query.categoryId}
AND a.id in (SELECT article_id FROM sys_article_tag WHERE tag_id = #{query.tagId})
order by a.create_time desc

SELECT CASE WHEN COUNT(id) > 0 THEN 1 ELSE 0 END as status
FROM sys_article_collect
WHERE user_id = #{userId}
  AND article_id = #{articleId}

SELECT user_id
FROM sys_article_collect
WHERE article_id = #{articleId}

SELECT a.id, a.title, a.summary, a.cover, a.content_md, a.quantity, a.status, a.create_time, c.name AS categoryName, (SELECT COUNT(sc.id) FROM sys_comment sc WHERE sc.article_id = a.id) AS comment_num, (SELECT COUNT(sal.id) FROM sys_article_like sal WHERE sal.article_id = a.id) AS like_num FROM sys_article a LEFT JOIN sys_category c ON a.category_id = c.id WHERE a.user_id = #{article.userId}
AND a.status = #{article.status}
AND a.title like concat('%',#{article.title},'%')
order by a.create_time desc
